patch:
diff --git a/rich/_export_format.py b/rich/_export_format.py
index 094d2dc2..ad3bd272 100644
--- a/rich/_export_format.py
+++ b/rich/_export_format.py
@@ -1,5 +1,6 @@
 CONSOLE_HTML_FORMAT = """\
 <!DOCTYPE html>
+<html>
 <head>
 <meta charset="UTF-8">
 <style>
@@ -10,7 +11,6 @@ body {{
 }}
 </style>
 </head>
-<html>
 <body>
     <pre style="font-family:Menlo,'DejaVu Sans Mono',consolas,'Courier New',monospace"><code>{code}</code></pre>
 </body>
@@ -22,35 +22,35 @@ CONSOLE_SVG_FORMAT = """\
     <!-- Generated with Rich https://www.textualize.io -->
     <style>

-    @font-face {{
+    @font-face {
         font-family: "Fira Code";
         src: local("FiraCode-Regular"),
                 url("https://cdnjs.cloudflare.com/ajax/libs/firacode/6.2.0/woff2/FiraCode-Regular.woff2") format("woff2"),
                 url("https://cdnjs.cloudflare.com/ajax/libs/firacode/6.2.0/woff/FiraCode-Regular.woff") format("woff");
         font-style: normal;
         font-weight: 400;
-    }}
-    @font-face {{
+    }
+    @font-face {
         font-family: "Fira Code";
         src: local("FiraCode-Bold"),
                 url("https://cdnjs.cloudflare.com/ajax/libs/firacode/6.2.0/woff2/FiraCode-Bold.woff2") format("woff2"),
                 url("https://cdnjs.cloudflare.com/ajax/libs/firacode/6.2.0/woff/FiraCode-Bold.woff") format("woff");
         font-style: bold;
         font-weight: 700;
-    }}
+    }

-    .{unique_id}-matrix {{
+    .{unique_id}-matrix {
         font-family: Fira Code, monospace;
         font-size: {char_height}px;
         line-height: {line_height}px;
         font-variant-east-asian: full-width;
-    }}
+    }

-    .{unique_id}-title {{
+    .{unique_id}-title {
         font-size: 18px;
         font-weight: bold;
         font-family: arial;
-    }}
+    }

     {styles}
     </style>
